-- Add bilingual content and Soft defaults without replacing edited content.
begin;
update public.profiles set data=data||jsonb_build_object('headline_en','"Computer Engineering student | Programming, Computer Architecture and Systems | Exploring software development"'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'headline_en' and data->'headline'='"Estudiante de Ingeniería Informática | Programación | Arquitectura de Computadoras | Sistemas | Interés en desarrollo de software y tecnología"'::jsonb;
update public.profiles set data=data||jsonb_build_object('degree_en','"Computer Engineering"'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'degree_en' and data->'degree'='"Ingeniería Informática"'::jsonb;
update public.profiles set data=data||jsonb_build_object('bio_en','"Computer Engineering student interested in programming, computer architecture, systems and software development."'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'bio_en' and data->'bio'='"Estudiante de Ingeniería Informática con interés en programación, arquitectura de computadoras, sistemas y desarrollo de software."'::jsonb;
update public.profiles set data=data||jsonb_build_object('about_title_en','"Understand the foundations.\nBuild what comes next."'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'about_title_en' and data->'about_title'='"Entender cómo funciona.\nConstruir lo que sigue."'::jsonb;
update public.profiles set data=data||jsonb_build_object('about_caption_en','"From hardware to software.\nFrom curiosity to practice."'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'about_caption_en' and data->'about_caption'='"Del hardware al software.\nDe la curiosidad a la práctica."'::jsonb;
update public.profiles set data=data||jsonb_build_object('about_en','"I am a Computer Engineering student with a curiosity for how computers work, from the underlying hardware to the software and systems built on top of it.\n\nI am building my knowledge of programming, computer architecture and electronics, connecting fundamental concepts with practical applications.\n\nI am looking to contribute to projects where I can keep learning, solve technical problems and collaborate with a team.\n\nI welcome opportunities to learn, collaborate and grow professionally in technology."'::jsonb) where id='00000000-0000-4000-8000-000000000001' and not data ? 'about_en' and data->'about'='"Soy estudiante de Ingeniería Informática con gran interés en el funcionamiento interno de las computadoras, la programación y los sistemas tecnológicos.\n\nActualmente me encuentro desarrollando mis conocimientos en áreas como programación, arquitectura de computadoras y electrónica, buscando siempre comprender cómo funcionan los sistemas desde lo más fundamental hasta su aplicación práctica.\n\nMe interesa participar en proyectos que me permitan seguir aprendiendo, enfrentar desafíos técnicos y trabajar en equipo para desarrollar soluciones tecnológicas.\n\nEstoy abierto a oportunidades de aprendizaje, colaboración y desarrollo profesional en el área de tecnología."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('hero_statement_en','"Software.\nSystems.\nPossibilities."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'hero_statement_en' and data->'hero_statement'='"Software.\nSistemas.\nPosibilidades."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('hero_description_en','"Computer Engineering student exploring programming, computer architecture and systems, with a focus on software development."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'hero_description_en' and data->'hero_description'='"Estudiante de Ingeniería Informática con interés en programación, arquitectura de computadoras, sistemas y desarrollo de software."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('projects_title_en','"Ideas taking shape."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'projects_title_en' and data->'projects_title'='"Ideas que toman forma."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('projects_empty_title_en','"Projects coming soon"'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'projects_empty_title_en' and data->'projects_empty_title'='"Próximos proyectos"'::jsonb;
update public.site_settings set data=data||jsonb_build_object('projects_empty_en','"A space for the things I am building."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'projects_empty_en' and data->'projects_empty'='"Un espacio para compartir lo que voy construyendo."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('gallery_title_en','"Beyond the code."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'gallery_title_en' and data->'gallery_title'='"Más allá del código."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('gallery_empty_en','"New images coming soon."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'gallery_empty_en' and data->'gallery_empty'='"Nuevas imágenes, próximamente."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('contact_title_en','"The next idea starts with a conversation."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'contact_title_en' and data->'contact_title'='"La próxima idea empieza con una conversación."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('experience_title_en','"Experience that adds perspective."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'experience_title_en' and data->'experience_title'='"Experiencia que suma."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('education_title_en','"Strong foundations.\nContinuous learning."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'education_title_en' and data->'education_title'='"Bases sólidas.\nAprendizaje continuo."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('skills_title_en','"An evolving toolkit."'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'skills_title_en' and data->'skills_title'='"Un toolkit en evolución."'::jsonb;
update public.site_settings set data=data||jsonb_build_object('hero_cta_en','"View projects"'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'hero_cta_en' and data->'hero_cta'='"Ver proyectos"'::jsonb;
update public.site_settings set data=data||jsonb_build_object('hero_about_cta_en','"About me"'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'hero_about_cta_en' and data->'hero_about_cta'='"Sobre mí"'::jsonb;
update public.site_settings set data=data||jsonb_build_object('hero_cv_cta_en','"Download CV"'::jsonb) where id='00000000-0000-4000-8000-000000000002' and not data ? 'hero_cv_cta_en' and data->'hero_cv_cta'='"Descargar CV"'::jsonb;
update public.experiences set data=data||jsonb_build_object('description_en','"Advised customers and provided in-store service.\nHandled sales and supported product presentation on the shop floor.\nOrganized stock and replenished merchandise.\nWorked with the team to uphold visual merchandising and customer service standards."'::jsonb) where id='00000000-0000-4000-8000-000000000010' and not data ? 'description_en' and data->'description'='"Atención y asesoramiento al cliente en tienda.\nGestión de ventas y manejo de productos en piso de venta.\nOrganización de stock y reposición de mercadería.\nTrabajo en equipo para mantener estándares de visual merchandising y servicio al cliente."'::jsonb;
update public.experiences set data=data||jsonb_build_object('description_en','"Sold graduation travel packages.\nAdvised customers on destinations, services and travel conditions.\nHandled enquiries and followed up with prospective customers.\nDeveloped communication, negotiation and sales skills."'::jsonb) where id='00000000-0000-4000-8000-000000000011' and not data ? 'description_en' and data->'description'='"Venta de paquetes de viajes de egresados.\nAtención y asesoramiento a clientes sobre destinos, servicios y condiciones del viaje.\nGestión de consultas y seguimiento de potenciales clientes.\nDesarrollo de habilidades de comunicación, negociación y ventas."'::jsonb;
update public.experiences set data=data||jsonb_build_object('description_en','"Supported administrative tasks in the operations department.\nOrganized and managed documentation.\nAssisted the team with day-to-day administrative work.\nGained my first professional experience in a corporate environment."'::jsonb) where id='00000000-0000-4000-8000-000000000012' and not data ? 'description_en' and data->'description'='"Apoyo en tareas administrativas dentro del área operativa.\nGestión y organización de documentación.\nColaboración con el equipo en tareas de soporte administrativo.\nPrimera experiencia profesional en un entorno corporativo."'::jsonb;
update public.site_settings set data='{"dark_enabled":true,"soft_enabled":true,"soft_background":"#f8f7f3","soft_primary":"#202126","soft_secondary":"#62616b","soft_accent":"#685487"}'::jsonb||data;
commit;
